{
    int r = 0;
    int i;

    in |= in << 1;
    in |= in << 2;
    in |= in << 4;
    in |= in << 8;
    in |= in << 16;
    in |= in << 32;

    for (i = 0; i < 64; ++i)
        r += (int)(((in >> i) & UINT64_C(1)) ^ UINT64_C(1));

    return r;
}
